const data = $json.data || {};
const titulo = data.titulo_noticia || '';
const cuerpo = data.cuerpo_noticia || '';
const documentId = data.documentId || '';

// La portada viene poblada (single media) desde el GET de Strapi.
const portada = data.foto_portada_noticia || null;
let imagenUrl = '';
if (portada) {
  const f = portada.formats || {};
  imagenUrl = (f.medium && f.medium.url) || (f.large && f.large.url) || portada.url || '';
  if (imagenUrl && !imagenUrl.startsWith('http')) {
    imagenUrl = $env.STRAPI_PUBLIC_URL + imagenUrl;
  }
}

const baseFront = ($env.FRONTEND_URL || '').replace(/\/+$/, '');
const enlace = baseFront + '/news/' + documentId;

const tit = titulo;
const cue = cuerpo;
const lin = enlace;
const img = imagenUrl;

const prompt = `Sos el community manager de la Asociacion de Futbol de AFAUTAL. Recibis una noticia institucional y tenes que generar UNA version de post por red social, en tono oficial, serio pero cercano, sin sensacionalismo.

NOTICIA:
- Titulo: ${tit}
- Cuerpo: ${cue}
- Enlace noticia completa: ${lin}
- Imagen portada (URL publica): ${img}

REGLAS:
1. Tono institucional de AFAUTAL, espanol chileno neutro.
2. Longitudes maximas:
   - twitter: max 280 caracteres (incluye el enlace).
   - instagram: max 2200 caracteres (caption, pocos hashtags).
   - facebook: max 5000 caracteres (resumen completo).
   - linkedin: max 3000 caracteres (tono profesional).
3. Cada version invita a leer la noticia completa incluyendo el enlace.
4. No inventar datos que no esten en la noticia. Respetar fechas/horarios/lugares si aparecen.

Respondé SOLO con JSON valido (sin markdown, sin texto alrededor), con este esquema exacto:
{
  "twitter": "...",
  "instagram": "...",
  "facebook": "...",
  "linkedin": "..."
}`;

const provider = String($env.AI_PROVIDER || 'anthropic').toLowerCase();
const model = $env.AI_MODEL || (provider === 'openai' ? 'gpt-4o-mini' : 'claude-sonnet-4-20250514');
const maxTokens = Number($env.AI_MAX_TOKENS || 2000);

let payload;
if (provider === 'openai') {
  payload = { model, max_tokens: maxTokens, messages: [{ role: 'user', content: prompt }] };
} else {
  payload = { model, max_tokens: maxTokens, messages: [{ role: 'user', content: prompt }] };
}

return [{ json: { titulo, cuerpo, documentId, imagenUrl, enlace, prompt, payload } }];

// Toma de nuevo el item de '03' para conservar titulo/enlace/imagen.
let prev = {};
try { prev = $('03 - Armar request IA').first().json; } catch (e) {}

const res = $json;
let content = '';
if (String($env.AI_PROVIDER).toLowerCase() === 'openai') {
  content = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || '';
} else {
  content = (res.content && res.content[0] && res.content[0].text) || (typeof res.content === 'string' ? res.content : '');
}

let versions = null;
let errorMsg = null;
try {
  const raw = String(content)
    .replace(/^\s*```(?:json)?\s*/i, '')
    .replace(/\s*```\s*$/, '')
    .trim();
  versions = JSON.parse(raw);
  if (!versions || typeof versions.twitter !== 'string') {
    throw new Error('la IA no devolvio las 4 versiones esperadas');
  }
} catch (e) {
  errorMsg = (e && e.message ? e.message : 'JSON invalido') + ' | respuesta IA: ' + String(content).slice(0, 400);
}

const okItem = { ...prev, versions, parseOk: true, parseError: null };
const errItem = { ...prev, versions, parseOk: false, parseError: errorMsg };
return [[{ json: okItem }], [{ json: errItem }]];

const t = $('03 - Armar request IA').first().json;
const v = $json.versions || {};

const bodyToCreate = {
  titulo_original: t.titulo,
  enlace_noticia: t.enlace,
  imagen_portada_url: t.imagenUrl,
  estado: 'pendiente',
  texto_facebook: (v.facebook || '').toString(),
  texto_instagram: (v.instagram || '').toString(),
  texto_linkedin: (v.linkedin || '').toString(),
  texto_twitter: (v.twitter || '').toString()
};

return [{ json: { bodyToCreate } }];

